cd /workspace; cat >> demandsci/warehouse.py <<'EOF'


def stores(con: sqlite3.Connection) -> pd.DataFrame:
    return pd.read_sql_query("SELECT store_id, delivery_slot, delivery_time FROM stores", con)


def hourly_sales(con: sqlite3.Connection) -> pd.DataFrame:
    return pd.read_sql_query("SELECT store_id, sku_id, date, hour, units FROM sales_hourly", con)


def inventory(con: sqlite3.Connection) -> pd.DataFrame:
    return pd.read_sql_query(
        "SELECT store_id, sku_id, date, on_hand_open, delivered_units, delivered_at, on_hand_close FROM inventory_daily",
